		}
	}
	[settingsWindow orderOut:nil];
	
	[window makeKeyAndOrderFront:nil];
	[self togglePreview:nil];
	[self performSelector:@selector(_selfTestSnapshotPreview) withObject:nil afterDelay:2.0];
}

