	for (NSWindow *aWindow in [NSApp windows]) {
		if (aWindow != window && [aWindow isVisible] && ![aWindow toolbar] && NSWidth([aWindow frame]) > 200)
			PrintSnapshotOfWindow(aWindow, @"preview");
